using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    // Technical namespaces the business layers must not reach into.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.Net", "System.IO", "System.Data", "System.Text.Json", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
    ];

    [Fact]
    public void Domain_does_not_depend_on_other_layers()
        => AssertNoViolations(Types.InAssembly(typeof(Money).Assembly)
            .ShouldNot().HaveDependencyOnAny(ApplicationNs, InfrastructureNs));

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
        => AssertNoViolations(Types.InAssembly(typeof(AuthorizePayment).Assembly)
            .ShouldNot().HaveDependencyOn(InfrastructureNs));

    [Fact]
    public void Business_layers_do_not_use_technical_details()
    {
        AssertNoViolations(Types.InAssembly(typeof(Money).Assembly)
            .ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));
        AssertNoViolations(Types.InAssembly(typeof(AuthorizePayment).Assembly)
            .ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));
    }

    [Fact]
    public void Infrastructure_assembly_is_the_one_under_test()
        => Assert.NotEmpty(Types.InAssembly(typeof(HttpPaymentGateway).Assembly).GetTypes());

    private static void AssertNoViolations(ConditionList rule)
    {
        var result = rule.GetResult();
        Assert.True(result.IsSuccessful, "Layer violations: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
